  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1220;
      --panel: #111a2b;
      --panel-2: #162238;
      --text: #e5eefc;
      --muted: #96a3b8;
      --border: #2a3954;
      --focus: #7aa7ff;
      --error: #ff6b8a;
      --success: #61d39e;
      --shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, rgba(122, 167, 255, 0.15), transparent 35%),
        linear-gradient(180deg, #08101d 0%, #0b1220 100%);
      display: grid;
      place-items: center;
      padding: 32px 16px;
    }

    .card {
      width: min(100%, 680px);
      background: linear-gradient(180deg, rgba(17, 26, 43, 0.96), rgba(11, 18, 32, 0.96));
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 24px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .card-header {
      padding: 32px 32px 0;
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(1.7rem, 3vw, 2.3rem);
      line-height: 1.1;
    }

    .subtitle {
      margin: 0;
      color: var(--muted);
      line-height: 1.5;
    }

    form {
      padding: 28px 32px 32px;
    }

    .form-field {
      margin-bottom: 18px;
    }

    label {
      display: inline-block;
      margin-bottom: 8px;
      font-weight: 600;
    }

    input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 14px 16px;
      background: rgba(255, 255, 255, 0.03);
      color: var(--text);
      font-size: 1rem;
      outline: none;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
    }

    input::placeholder {
      color: #7b89a5;
    }

    input:focus {
      border-color: var(--focus);
      box-shadow: 0 0 0 4px rgba(122, 167, 255, 0.18);
      background: rgba(255, 255, 255, 0.05);
    }

    input[aria-invalid="true"] {
      border-color: var(--error);
      box-shadow: 0 0 0 4px rgba(255, 107, 138, 0.12);
    }

    .helper-text,
    .error-message {
      display: block;
      margin-top: 8px;
      font-size: 0.92rem;
      line-height: 1.45;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-message {
      color: var(--error);
      min-height: 1.3em;
    }

    .submit-row {
      display: flex;
      justify-content: flex-end;
      margin-top: 24px;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      background: linear-gradient(135deg, #7aa7ff, #4f7cff);
      color: white;
      font-weight: 700;
      font-size: 1rem;
      cursor: pointer;
      box-shadow: 0 12px 24px rgba(79, 124, 255, 0.28);
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 16px 30px rgba(79, 124, 255, 0.34);
    }

    button:focus-visible {
      outline: 3px solid rgba(122, 167, 255, 0.45);
      outline-offset: 3px;
    }

    .status {
      margin-top: 16px;
      padding: 14px 16px;
      border-radius: 14px;
      background: rgba(97, 211, 158, 0.12);
      border: 1px solid rgba(97, 211, 158, 0.28);
      color: var(--success);
      display: none;
    }

    .status.show {
      display: block;
    }
  </style>
</head>
<body>
  <main class="card">
    <div class="card-header">
      <h1>Contact Support</h1>
      <p class="subtitle">Send us a message and we'll get back to you as soon as possible.</p>
    </div>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="fullName">Full name</label>
        <input id="fullName" name="fullName" type="text" autocomplete="name" placeholder="Jane Doe" required />
        <span class="error-message" id="fullName-error" aria-live="polite"></span>
      </div>

      <div class="form-field">
        <label for="email">Email address</label>
        <input id="email" name="email" type="email" autocomplete="email" placeholder="jane@example.com" required />
        <span class="error-message" id="email-error" aria-live="polite"></span>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="555-123-4567" />
        <span class="helper-text" id="phone-help">Optional. Enter 555-123-4567 or +1 555-123-4567.</span>
        <span class="error-message" id="phone-error" aria-live="polite"></span>
      </div>

      <div class="submit-row">
        <button type="submit">Submit request</button>
      </div>

      <div class="status" id="form-status" aria-live="polite"></div>
    </form>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const fullName = document.getElementById('fullName');
    const email = document.getElementById('email');
    const phone = document.getElementById('phone');
    const status = document.getElementById('form-status');

    const fields = [
      {
        input: fullName,
        errorId: 'fullName-error',
        validate: (value) => value.trim() ? '' : 'Full name is required.'
      },
      {
        input: email,
        errorId: 'email-error',
        validate: (value) => {
          if (!value.trim()) return 'Email address is required.';
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) return 'Enter a valid email address.';
          return '';
        }
      },
      {
        input: phone,
        errorId: 'phone-error',
        validate: (value) => {
          if (!value.trim()) return '';
          if (!/^(?:\+?\d{1,3}[-.\s]?)?(?:\(?\d{3}\)?[-.\s]?){2}\d{4}$/.test(value.trim())) {
            return 'Enter a valid phone number, such as 555-123-4567.';
          }
          return '';
        }
      }
    ];

    function setError(field, message) {
      const errorEl = document.getElementById(field.errorId);
      field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
      errorEl.textContent = message;
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setError(field, message);
      return !message;
    }

    fields.forEach((field) => {
      field.input.addEventListener('blur', () => validateField(field));
      field.input.addEventListener('input', () => {
        if (field.input.getAttribute('aria-invalid') === 'true') {
          validateField(field);
        }
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.classList.remove('show');
      status.textContent = '';

      const isValid = fields.every(validateField);

      if (!isValid) {
        return;
      }

      status.textContent = 'Your support request is ready to send.';
      status.classList.add('show');
      form.reset();
      fields.forEach((field) => setError(field, ''));
    });
  </script>
</body>
</html>
